Q: Is it possible to create a property of type BindingBase? A: <p>In my case I was creating an AttachedProperty, so this meant that a normal CLR property was not possible.</p>

<p>The trick is to declare the DependencyProperty type as BindingExpressionBase rather than BindingBase.</p>

<p>You can then get to BindingBase from the <a href="https://learn.microsoft.com/en-us/dotnet/api/system.windows.data.bindingexpressionbase.parentbindingbase?view=netframework-4.8" rel="nofollow noreferrer">BindingExpressionBase.ParentBindingBase</a> property.</p>

<pre><code>public static class Example
{
    public static BindingExpressionBase GetMyBinding(DependencyObject obj)
    {
        return (BindingExpressionBase)obj.GetValue(MyBindingProperty);
    }
    public static void SetMyBinding(DependencyObject obj, BindingExpressionBase value)
    {
        obj.SetValue(MyBindingProperty, value);
    }

    public static readonly DependencyProperty MyBindingProperty =
        DependencyProperty.RegisterAttached(
            name:               "MyBinding",
            propertyType:       typeof(BindingExpressionBase),
            ownerType:          typeof(Example),
            defaultMetadata:    new FrameworkPropertyMetadata(null));
}

DependencyObject obj = ...;
BindingBase bb = Example.GetMyBinding(obj)?.ParentBindingBase;

</code></pre>
